{
     "title": "CSCI-488: CS Undergraduate Summer Co-op Orientation",
     "learningObjectives": [
       "Students will define the minimum time and credit requirements for summer co-op registration.",
       "Students will articulate the dual-document grading mechanism and consistency standard for co-op evaluation.",
       "Students will apply ACM ethical principles and responsible research practices to professional co-op work."
     ],
     "beats": [
       {
         "title": "Program Overview and Credit Status",
         "claim": "Students registered for CSCI-488 are considered to have full-time status by RIT.",
         "example": "A student enrolled in the summer co-op program receives full-time enrollment credits for housing, financial aid, and academic advising purposes.",
         "visualDirection": "Display a side-by-side comparison graphic showing 'Standard Semester' vs. 'Summer Co-op' with a highlighted badge stating 'Full-Time Status' under the co-op column.",
         "sourceIds": ["rit-csci-488"]
       },
       {
         "title": "Summer Term Registration Requirements",
         "claim": "Students must work a minimum of 12 weeks and 35 hours per week to register for the summer co-op.",
         "example": "A student schedules a 12-week summer placement with a weekly commitment of exactly 35 hours to meet the minimum threshold.",
         "visualDirection": "Insert a calendar timeline graphic spanning 12 weeks with a recurring weekly block labeled '35 Hours/Week' and a checkmark at the end.",
         "sourceIds": ["rit-csci-488"]
       },
       {
         "title": "Prerequisite Coursework",
         "claim": "Completion of CSCI-099 or an equivalent course is required before registering for CSCI-488.",
         "example": "A student verifies their transcript shows a passing grade in CSCI-099 before submitting the summer co-op registration form.",
         "visualDirection": "Show a prerequisite flowchart with an arrow pointing from 'CSCI-099/Equivalent' to 'CSCI-488 Registration', with a lock icon indicating the requirement.",
         "sourceIds": ["rit-csci-488"]
       },
       {
         "title": "Student Work Report Requirement",
         "claim": "Students must complete a student co-op work report for each term they are registered for.",
         "example": "A student submits a structured PDF report detailing project scope, technical challenges, and deliverables after the summer term.",
         "visualDirection": "Render a document template with sections for 'Project Description', 'Technical Implementation', and 'Deliverables' to illustrate the report structure.",
         "sourceIds": ["rit-csci-488"]
       },
       {
         "title": "Supervisor Evaluation Process",
         "claim": "Students are evaluated each term by their assigned supervisor through a formal evaluation document.",
         "example": "A supervisor completes a standardized form rating the student's technical contributions, communication, and professional conduct.",
         "visualDirection": "Display a supervisor evaluation form layout with fields for 'Technical Competence', 'Professional Conduct', and 'Overall Assessment'.",
         "sourceIds": ["rit-csci-488"]
       },
       {
         "title": "Grading Consistency Standard",
         "claim": "A satisfactory grade is awarded only when both the student report and supervisor evaluation are generally consistent.",
         "example": "The academic advisor reviews both documents and confirms that the student's self-assessment aligns with the supervisor's ratings before finalizing the grade.",
         "visualDirection": "Create a two-column comparison table showing 'Student Report' and 'Supervisor Evaluation' with a central 'Consistency Check' column indicating alignment.",
         "sourceIds": ["rit-csci-488"]
       },
       {
         "title": "ACM Ethical Practice in Co-op",
         "claim": "Computing professionals must avoid harm, be honest, and strive for high quality in both processes and products.",
         "example": "A co-op student implements robust security measures and documents all code changes to ensure transparency and prevent unintended system harm.",
         "visualDirection": "Show a checklist graphic with icons representing 'Avoid Harm', 'Honesty', 'High Quality', and 'Robust Security' as co-op competencies.",
         "sourceIds": ["acm-code-of-ethics"]
       },
       {
         "title": "Responsible Technical Communication",
         "claim": "Responsible technical communication requires distinguishing claims from evidence and citing prior work accurately.",
         "example": "A student's co-op report includes a literature review section that explicitly cites prior research and clearly separates empirical results from theoretical claims.",
         "visualDirection": "Display a before-and-after comparison of a paragraph showing how to properly distinguish 'claims' from 'evidence' using citation markers.",
         "sourceIds": ["acm-research-practice"]
       },
       {
         "title": "Research Integrity and Documentation",
         "claim": "Authors should preserve research integrity by avoiding fabrication and ensuring methods are reproducible.",
         "example": "A student maintains version-controlled code repositories and detailed methodology notes so that their co-op project can be independently verified.",
         "visualDirection": "Illustrate a workflow diagram showing 'Method Documentation', 'Version Control', and 'Reproducibility Check' as mandatory co-op practices.",
         "sourceIds": ["acm-research-practice"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Students must verify registration eligibility, document consistency, and ethical compliance before term completion.",
         "example": "A student uses a final checklist to confirm 12-week/35-hour commitment, report-supervisor alignment, and ACM ethical standards before submitting grades.",
         "visualDirection": "Provide a compact checklist graphic with three main categories: 'Registration & Hours', 'Documentation Consistency', and 'Ethical & Research Standards', each with a checkbox.",
         "sourceIds": ["rit-csci-488", "acm-code-of-ethics"]
       }
     ]
   }
